"""Cancellation tombstones do not require an event to exist."""

from django.core.exceptions import ValidationError

from bloomerp.models.communication.calendar import CalendarSchedulingCancellation
from bloomerp.router import router
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)
from bloomerp.tests.communication.calendar_fixtures import STAMP


class TestCalendarSchedulingCancellationModel(BloomerpModelTestCase):
    model = CalendarSchedulingCancellation

    def get_test_scenarios(self) -> list[ModelScenario[CalendarSchedulingCancellation]]:
        """Retain and uniquely identify cancellation revisions before invitation delivery."""
        return [
            ModelScenario(
                name="One cancellation identity per organizer and affected attendee",
                create_args={
                    "calendar_uid": "cancelled@test",
                    "organizer_email": "organizer@example.com",
                    "sequence": 1,
                    "dtstamp": STAMP,
                },
                create_validators=self.has_no_public_routes,
                update_args={"sequence": 2},
                update_validators=self.is_newer,
            ),
            ModelScenario(
                name="Duplicate cancellation identity is rejected",
                create_args=self.duplicate_args,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
        ]

    def is_newer(self, cancellation: CalendarSchedulingCancellation) -> bool:
        """Confirm the stored revision can advance without creating a meeting."""
        return cancellation.sequence == 2

    def duplicate_args(self) -> dict[str, object]:
        """Attempt to store a second tombstone for the same organizer and UID."""
        values = {
            "calendar_uid": "cancelled@test",
            "organizer_email": "organizer@example.com",
            "sequence": 1,
            "dtstamp": STAMP,
        }
        CalendarSchedulingCancellation.objects.create(**values)
        return values

    def has_no_public_routes(self, instance: CalendarSchedulingCancellation) -> bool:
        """Keep durable scheduling state out of navigation, CRUD, and generated APIs."""
        return not router.get_routes_by_model(type(instance))
